{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The glass diver arrives at the ruined city gates.",
      "visual_description": "A massive wrought-iron gate hangs crookedly between two crumbling stone towers. The glass diver stands before it, his diving helmet reflecting the broken spires and faded royal banners that flap in the wind.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara the cartographer studies a torn map under a flickering lamp.",
      "visual_description": "Mara kneels on rubble, unrolling a stained parchment map. The oracle lamp sits beside her, its single flame-eye casting a warm pool of light on the ink lines. The tin fox sniffs at the edges of the paper.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp warns of a cursed tower ahead.",
      "visual_description": "The lamp's flame-eye flickers intensely as it speaks. Its light throws long shadows from a twisted black tower in the distance. A heavy mist clings to the tower's base.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 4,
      "caption": "The tin fox scouts ahead through a collapsed archway.",
      "visual_description": "The small metal fox tiptoes over fallen stones, its key-wind tail turning slowly. Blue glass eyes scan a dark passage. Faded royal banners hang torn above the arch.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "They encounter a frightened townspeople huddled in a courtyard.",
      "visual_description": "A group of townsfolk cluster around a cold fountain, their faces pale and drawn. They clutch bundles and children, glancing nervously at the patrols that march in the distance. The glass diver approaches carefully.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 6,
      "caption": "Armored patrols march past a row of magic doors.",
      "visual_description": "A squad of armored figures clanks through a colonnade lined with doors that glow with faint runes. The tin fox presses itself flat behind a broken pillar, watching.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "The sleeping tax collector dozes on a throne of ledgers.",
      "visual_description": "In a half-collapsed hall, the tax collector snores loudly, his head pillowed on a stack of stamped papers. His sleeves are covered in ink stamps. Mara sighs and steps over his outstretched legs.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "The oracle lamp reveals a hidden passage behind a tapestry.",
      "visual_description": "The lamp's flame illuminates a dusty tapestry showing a faded crest. Behind it, a narrow stone staircase descends into darkness. The glass diver brushes the cloth aside.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 9,
      "caption": "They navigate a room of shifting mirrors.",
      "visual_description": "Hundreds of mirrors of all sizes cover the walls of a circular chamber. Reflections multiply endlessly. The glass diver steps forward, his helmet catching fractured images of the group.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "The tin fox disables a pressure plate trap.",
      "visual_description": "The tiny fox inserts its tail into a mechanism on the floor. Gears click and the trap retracts with a soft hiss. Mara watches from the doorway, map in hand.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "The glass diver swims through a window into a locked vault.",
      "visual_description": "The diver presses his helmet against a window pane, then his body becomes fluid and passes through the glass. Inside, shelves of dusty scrolls line the walls. He lands silently on the stone floor.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "The oracle lamp warns of a patrol rounding the corner.",
      "visual_description": "The lamp's eye glows red as it whispers urgently. Mara grabs the tin fox and presses against the wall. The sound of heavy boots echoes closer.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "They find the sleeping tax collector again, still snoring.",
      "visual_description": "In a different part of the ruin, the tax collector has somehow relocated to a pile of rubble, still clutching his ledger. A stamp is stuck to his cheek. The glass diver shakes his head.",
      "characters": ["glass_diver", "sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 14,
      "caption": "The glass diver peers into a magic door and sees a way out.",
      "visual_description": "A tall door of polished obsidian reflects the diver's helmet. As he looks, the surface ripples and shows an image of a bridge beyond the city walls. He taps the glass to signal the others.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "Mara marks a safe route on her map as the lamp glows.",
      "visual_description": "Mara kneels, inking a path through the ruins. The oracle lamp floats beside her, casting steady light. The tin fox stands guard on a nearby stone.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "The group crosses a crumbling bridge under a full moon.",
      "visual_description": "A long stone bridge arches over a chasm. Several stones are missing. The glass diver leads, testing each step. Mara follows, holding the lamp high. The tin fox scurries behind.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "They pass the sleeping tax collector one last time on the bridge.",
      "visual_description": "Incredibly, the tax collector lies asleep across the bridge's midpoint, ledger open on his chest. The group carefully steps around him as he mutters in his sleep.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "They reach the far side and look back at the ruined city.",
      "visual_description": "The group stands on a hill outside the city. Behind them, the ruined spires and banners are silhouetted against the dawn sky. The glass diver removes his helmet and breathes fresh air. Mara folds her map. The lamp's flame dims to a quiet glow.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    }
  ]
}

